341:         cps.length > 0
342:           ? `${cps.length} Entire checkpoint(s) recorded on branch`
343:           : `0 Entire checkpoints recorded on ${branch} (ensure Pi/Entire hooks are active before committing)`,
344:     });
345:   }
346: 
347:   // 3. Verify no outgoing checkpoints are left unpushed
348:   const outgoingRes = await runCmd(execFileAsync, "entire", ["checkpoint", "list", "--outgoing", "--json"]);
349:   if (outgoingRes.ok) {
350:     try {
351:       const parsed = JSON.parse(outgoingRes.stdout || '{"checkpoints":[]}');
352:       const waiting = Array.isArray(parsed?.checkpoints) ? parsed.checkpoints : [];
353:       if (waiting.length > 0) {
354:         const first = waiting[0];
355:         const example = first.commit ? `${first.checkpoint_id}@${first.commit}` : first.checkpoint_id;
356:         checks.push({
357:           name: "gate.entire_checkpoints_pushed",
358:           status: "fail",
359:           detail: `${waiting.length} checkpoint(s) not yet pushed to remote (run: entire checkpoint push ${example} --json)`,
360:         });
361:       } else {
362:         checks.push({
363:           name: "gate.entire_checkpoints_pushed",
364:           status: "pass",
365:           detail: "All local Entire checkpoints are pushed to remote",
366:         });
367:       }
368:     } catch {
369:       // ignore parse errors on non-git-refs backends
370:     }
371:   }
372: 
373:   return checks;
374: }
