376: export function validateShadowPrBody(body, issueNumber = null) {
377:   const text = typeof body === "string" ? body : "";
378:   const hasShadowMarker = text.includes("<!-- entire-shadow-pr -->");
379:   let hasIssueClosingKeyword = true;
380:   if (issueNumber !== null && issueNumber !== undefined) {
381:     const re = new RegExp(
382:       `\\b(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\\s+(?:[\\w.-]+\\/[\\w.-]+)?#${issueNumber}\\b`,
383:       "i",
384:     );
385:     hasIssueClosingKeyword = re.test(text);
386:   }
387:   return {
388:     hasShadowMarker,
389:     hasIssueClosingKeyword,
390:   };
391: }
