393: export function evaluateTrailGates(trailJson, expectedBranch = null) {
394:   const changes = Array.isArray(trailJson?.changes) ? trailJson.changes : [];
395:   const change = expectedBranch
396:     ? changes.find((c) => c.branch === expectedBranch) ?? changes[0]
397:     : changes[0];
398: 
399:   if (!change) {
400:     return {
401:       ok: false,
402:       detail: "No branch change linked to Trail",
403:       trailNumber: trailJson?.number ?? null,
404:       trailUrl: trailJson?.url ?? null,
405:     };
406:   }
407: 
408:   const headSha = change?.mergeability?.head_sha ?? null;
409:   const conflictStatus = change?.mergeability?.conflict_status ?? null;
410:   const trailMergeable = change?.mergeability?.mergeable;
411:   const gates = Array.isArray(change?.mergeability?.gates) ? change.mergeability.gates : [];
412:   const approvalsGate = gates.find((g) => g.gate_key === "approvals");
413:   const findingsGate = gates.find((g) => g.gate_key === "findings");
414: 
415:   const approvalsPassed = approvalsGate ? approvalsGate.status === "passed" : false;
416:   const findingsPassed = findingsGate ? findingsGate.status === "passed" : true;
417:   const openBlocking = findingsGate?.value?.agent_blocking_findings ?? 0;
418: 
419:   const problems = [];
420:   if (conflictStatus && conflictStatus !== "clean") {
421:     problems.push(`conflict_status="${conflictStatus}" (run 'but pull' and resolve conflicts via 'but resolve')`);
422:   }
423:   if (!approvalsPassed) {
424:     problems.push(`approvals gate status="${approvalsGate?.status ?? "missing"}" (${approvalsGate?.rationale ?? "unapproved"})`);
425:   }
426:   if (!findingsPassed || openBlocking > 0) {
427:     problems.push(`findings gate status="${findingsGate?.status ?? "unknown"}" (blocking=${openBlocking})`);
428:   }
429:   for (const gate of gates) {
430:     if (gate.gate_key === "approvals" || gate.gate_key === "findings") continue;
431:     if (gate.blocking !== false && gate.status !== "passed" && gate.status !== "skipped") {
432:       problems.push(
433:         `${gate.gate_key} gate status="${gate.status ?? "unknown"}" (${gate.rationale ?? "rebase onto origin/main with 'but pull'"})`,
434:       );
435:     }
436:   }
437:   if (problems.length === 0 && trailMergeable === false) {
438:     problems.push("trail mergeability.mergeable=false (check 'entire trail show --json' for pending/failed gates)");
439:   }
440: 
441:   return {
442:     ok: problems.length === 0,
443:     detail:
444:       problems.length === 0
445:         ? `Trail #${trailJson?.number} gates passed at ${headSha ? headSha.slice(0, 8) : "HEAD"}`
446:         : `Trail #${trailJson?.number} gate issues: ${problems.join("; ")}`,
447:     trailNumber: trailJson?.number ?? null,
448:     trailUrl: trailJson?.url ?? null,
449:     headSha,
450:   };
451: }
