608:           detail: `Invalid JSON in ~/.pi/agent/mcp.json: ${err.message}`,
609:         });
610:       }
611:     }
612: 
613:     if (typeof fetchImpl === "function") {
614:       try {
615:         const controller = new AbortController();
616:         const timer = setTimeout(() => controller.abort(), 1500);
617:         const resp = await fetchImpl("http://127.0.0.1:9010/mcp", {
618:           method: "GET",
619:           signal: controller.signal,
620:         });
621:         clearTimeout(timer);
622:         checks.push({
623:           name: "web.browseros_neo_live",
624:           status: "pass",
625:           detail: `BrowserOS Neo reachable on 127.0.0.1:9010 (HTTP ${resp.status})`,
