627:       } catch {
628:         checks.push({
629:           name: "web.browseros_neo_live",
630:           status: "warn",
631:           detail: "BrowserOS Neo not listening on 127.0.0.1:9010 (launch BrowserOS Neo before Tier 4 fetches)",
632:         });
633:       }
634:     }
