637:   // 5. Duplicate-work / claim check (start-of-task only; opt-in via --issue)
638:   if (issue) {
639:     const duplicate = await checkDuplicateWork({ issue, cwd, execFileAsync });
640:     if (duplicate.error) {
641:       checks.push({
642:         name: "workflow.duplicate_work",
643:         status: "warn",
644:         detail: duplicate.error,
645:       });
646:     } else if (duplicate.ok) {
647:       checks.push({
648:         name: "workflow.duplicate_work",
649:         status: "pass",
650:         detail: `No open PRs, worktrees, or branches already claim #${issue}`,
651:       });
652:     } else {
653:       const detail = duplicate.duplicates
654:         .map((d) => `${d.label} (${d.detail})`)
655:         .join("; ");
656:       checks.push({
657:         name: "workflow.duplicate_work",
658:         status: "fail",
659:         detail: `${duplicate.duplicates.length} item(s) already claim #${issue}: ${detail}. Resume the existing worktree/branch instead of spawning a new one.`,
660:       });
661:     }
662:   }
663: 
664:   const failed = checks.filter((c) => c.status === "fail" || (strict && c.status === "warn"));
665:   return {
666:     ok: failed.length === 0,
667:     mode: effectiveMode,
668:     checks,
669:   };
670: }
