875: function formatReport(result) {
876:   const icon = (s) => (s === "pass" ? "PASS" : s === "warn" ? "WARN" : "FAIL");
877:   const header = result.gate
878:     ? `Completion Gate (${result.gate}) — branch=${result.branch}${result.issue ? ` issue=#${result.issue}` : ""}`
879:     : `Preflight Check (mode=${result.mode})`;
880:   const lines = [header, "-".repeat(header.length)];
881:   for (const c of result.checks) {
882:     lines.push(`[${icon(c.status)}] ${c.name}: ${c.detail}`);
883:   }
884:   lines.push(`Result: ${result.ok ? "READY" : "NOT READY"}`);
885:   return lines.join("\n");
886: }
887: 
888: function printHelp() {
889:   console.log(`entire-orca-workflow preflight & completion gate
890: 
891: Usage:
892:   node scripts/preflight.mjs [--mode auto|core|web-modalities] [--issue <N>] [--strict] [--json]
893:   node scripts/preflight.mjs --gate in-review --branch <branch> [--issue <N>] [--repo <owner/repo>] [--json]
894: 
895: Options:
896:   --mode <mode>             Preflight mode: auto (default), core, or web-modalities
897:   --issue <number>          Start preflight: fail if an open PR, Orca worktree, or branch already claims #N.
898:                             Completion gate: issue number for Fixes #N + Project Status verification
899:   --gate in-review          Verify Trail, review/approval gate, shadow PR (<!-- entire-shadow-pr --> + Fixes #N),
900:                             Orca workspaceStatus=in-review + linked PR, and GitHub Project Status="In Review"
901:   --branch <branch>         Branch name for --gate (defaults to current Orca worktree branch)
902:   --repo <owner/repo>       GitHub repository (defaults to current Orca worktree project)
903:   --project-owner <owner>   GitHub Project owner (default: zzztimbo)
904:   --project-number <N>      GitHub Project number (default: 1)
905:   --strict                  Treat warnings as failures
906:   --json                    Emit machine-readable JSON
907:   -h, --help                Show this help
908: `);
909: }
910: 
911: const isMain = (() => {
912:   if (!process.argv[1]) return false;
913:   try {
914:     return fs.realpathSync(process.argv[1]) === fs.realpathSync(fileURLToPath(import.meta.url));
915:   } catch {
916:     return false;
917:   }
918: })();
919: 
920: if (isMain) {
921:   try {
922:     const opts = parseArgs(process.argv.slice(2));
923:     if (opts.help) {
924:       printHelp();
925:       process.exit(0);
926:     }
927:     const result = opts.gate ? await runCompletionGate(opts) : await runPreflight(opts);
928:     if (opts.json) {
929:       console.log(JSON.stringify(result, null, 2));
930:     } else {
931:       console.log(formatReport(result));
932:     }
933:     process.exit(result.ok ? 0 : 1);
934:   } catch (err) {
935:     console.error(`Error: ${err.message}`);
936:     process.exit(2);
937:   }
938: }

